head.script:
scwin.onpageload = function() {
    scwin.jsonData1 = [{
        "key": "무궁화꽃이피었습니다.",
        "value": "value1"
    }, {
        "key": "무궁화꽃이피었습니다.",
        "value": "value2"
    }, {
        "key": "무궁화꽃이피었습니다.",
        "value": "value3"
    }, {
        "key": "무궁화꽃이피었습니다.",
        "value": "value4"
    }, {
        "key": "무궁화꽃이피었습니다.",
        "value": "value5"
    }, {
        "key": "무궁화꽃이피었습니다.",
        "value": "value6"
    }];
    scwin.jsonData2 = [{
        "key": "무궁화1.",
        "value": "value1"
    }, {
        "key": "무궁화2.",
        "value": "value2"
    }, {
        "key": "무궁화3.",
        "value": "value3"
    }, {
        "key": "무궁화4.",
        "value": "value4"
    }, {
        "key": "무궁화5.",
        "value": "value5"
    }, {
        "key": "무궁화6.",
        "value": "value6"
    }];
    dataList1.setJSON(scwin.jsonData1);
};
scwin.onpageunload = function() {};
scwin.ccb_checkcombobox1_onviewchange = function(info) {
    ccb_checkcombobox2.setNodeSet("data:dataList2", "key", "value");
    setTimeout(function() {
        dataList2.setJSON(scwin.jsonData2);
    }, 2000);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox1_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox1_itemTable_1_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox1_btn_confirm').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox1_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox1_itemTable_2_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox1_btn_confirm').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox2_button').click()");
    WebSquare.wUnit.addCommand("pause", "3000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'ccb_checkcombobox2_itemTable_main').style.width == '148px'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
